private val listMarkerRegex = Regex("""^(•|\d+\.)\s+(.*)$""")

/**
 * Shared long-form body renderer for the "?" Screen Guide sheets and the Tutorials articles --
 * replaces a single big `Text` block with real paragraph/list structure, since a wall of one dense
 * paragraph was hard to scan. No new content model: still one plain string per call site (still one
 * translatable resource, still diffable per section), just parsed at render time into blocks.
 *
 * Convention: `\n\n` separates blocks (paragraphs or lists). A block renders as a list when EVERY
 * one of its `\n`-separated lines starts with `• ` (bullet) or `N. ` (ordered) -- otherwise the
 * whole block renders as one plain wrapped paragraph. A list item's marker sits in a fixed-width
 * column so a wrapped continuation line lines up under the item's own text, not under the marker
 * (the "hanging indent" a plain `Text` with an inline `•` character can't do on its own).
 */
@Composable
fun FormattedBodyText(
    text: String,
    style: TextStyle = MaterialTheme.typography.bodyMedium,
    color: Color = LocalPulseColors.current.onSurfaceMuted,
    modifier: Modifier = Modifier
) {
    val blockSpacing = dimensionResource(id = R.dimen.padding_medium)
    val itemSpacing = dimensionResource(id = R.dimen.padding_small)
    val blocks = text.split("\n\n").filter { it.isNotBlank() }

    Column(modifier = modifier) {
        blocks.forEachIndexed { blockIndex, block ->
            val lines = block.split("\n").filter { it.isNotBlank() }
            val items = lines.map { listMarkerRegex.matchEntire(it.trim()) }

            if (items.isNotEmpty() && items.all { it != null }) {
                Column(verticalArrangement = Arrangement.spacedBy(itemSpacing)) {
                    items.forEach { match ->
                        val (marker, body) = match!!.destructured
                        ListItemRow(marker = marker, body = body, style = style, color = color)
                    }
                }
            } else {
                Text(text = block, style = style, color = color)
            }

            if (blockIndex != blocks.lastIndex) {
                Spacer(modifier = Modifier.height(blockSpacing))
            }
        }
    }
}

@Composable
private fun ListItemRow(marker: String, body: String, style: TextStyle, color: Color) {
    Row {
        Text(
            text = marker,
            style = style,
            color = color,
            modifier = Modifier.width(dimensionResource(id = R.dimen.list_marker_column_width))
        )
        Text(text = body, style = style, color = color, modifier = Modifier)
    }
}

